import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BUOFcz_J.js";const m=JSON.parse('{"title":"Rho implementation stack","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/techstack.md","filePath":"concepts/techstack.md"}'),n={name:"concepts/techstack.md"};function d(s,e,i,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="rho-implementation-stack" tabindex="-1">Rho implementation stack <a class="header-anchor" href="#rho-implementation-stack" aria-label="Permalink to &quot;Rho implementation stack&quot;">​</a></h1><p>The package lock and owner entry inventory identify exact build inputs. This document records the current combination; it does not prescribe a visual style or future UI framework. <a href="/Rho/docs/concepts/architecture">Architecture</a> defines source ownership.</p><table tabindex="0"><thead><tr><th>Layer</th><th>Current implementation</th></tr></thead><tbody><tr><td>Local service and launcher</td><td>Node 22.22.x (24 and 26 also checked), TypeScript 5.9.3, built-in HTTP, Ajv 8.20.0</td></tr><tr><td>Public API</td><td>Generated JSON Schema request/response contracts; authenticated JSON and SSE</td></tr><tr><td>Browser application</td><td>React/React DOM 19.3.1, Vite 8.3.4, TypeScript</td></tr><tr><td>Workspace</td><td>Rho renders the owner&#39;s conditional composition tree as tabs and splits</td></tr><tr><td>Documents</td><td>Documents owner with a CodeMirror 6 view; Rho adds Python (lang-python), R (legacy mode) and Markdown (lang-markdown) by file name, each loaded on first use</td></tr><tr><td>Markdown</td><td>Markdown reader (UI extension over Documents) with markdown-it 14.3.2 and KaTeX 0.16.47, loaded when a Markdown view first shows</td></tr><tr><td>Review evidence</td><td>Files immutable captures, Annotations append-only human decisions, owner code/table comparison; Rho Graph and static offline export</td></tr><tr><td>Tables</td><td>Tables owner with AG Grid Community</td></tr><tr><td>Figures and charts</td><td>Original versioned media; Charts owner with ECharts</td></tr><tr><td>External Agent</td><td>Project-scoped MCP adapter and selected external Agent client</td></tr><tr><td>Managed execution</td><td>Public Core CLI and an independently held resident Host</td></tr><tr><td>Browser automation</td><td>Playwright 1.64.1 driving installed Google Chrome</td></tr></tbody></table><h2 id="local-service-and-workspace" tabindex="-1">Local service and workspace <a class="header-anchor" href="#local-service-and-workspace" aria-label="Permalink to &quot;Local service and workspace&quot;">​</a></h2><p>The browser has no shell, filesystem or Core access of its own. Its client calls named scoped operations on the local service. Credentials do not enter frontend assets. Reads and reconnects do not start or recover a Host.</p><p>View rendering and local cursor/scroll state stay in the browser; document content, undo, resource versions and execution facts stay with their owners. Layout writes use <code>composition.apply</code> or <code>composition.undo</code>, with the version actually observed. There is no additional layout persistence model to reconcile.</p><p>The installed application is assembled from selected component packages and a Core artifact. Native R and selected scientific libraries remain external runtime requirements. A component check does not accept an application combination.</p><p><a href="/Rho/docs/reference/frontend">Frontend</a> documents navigation and browser checks. <a href="/Rho/docs/reference/headless">Headless backend</a> documents installation and runtime limits. <a href="/Rho/docs/reference/release">Release</a> separates source publication from package distribution.</p>',8)])])}const u=t(n,[["render",d]]);export{m as __pageData,u as default};
